[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellStream Platform — Integrated Energy Data Management</title>
  <meta name="description" content="WellStream delivers integrated SaaS solutions for energy operators to manage well data, production, and land assets. Real-time data across your entire operation. Request a demo.">
  <link rel="canonical" href="https://www.wellstream.com/">
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://www.wellstream.com/">
  <meta property="og:title" content="WellStream Platform — Integrated Energy Data Management">
  <meta property="og:description" content="The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.">
  <meta property="og:image" content="https://www.wellstream.com/og-image.jpg">
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:title" content="WellStream Platform — Integrated Energy Data Management">
  <meta property="twitter:description" content="The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.">
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "SoftwareApplication",
    "name": "WellStream Platform",
    "description": "WellStream delivers integrated SaaS solutions for energy operators to manage well data, production, and land assets—streamlining operations and enhancing decision-making.",
    "@id": "https://www.wellstream.com/#organization",
    "url": "https://www.wellstream.com",
    "applicationCategory": "BusinessApplication",
    "operatingSystem": "Web, iOS, Android",
    "offers": { "@type": "Offer", "availability": "https://schema.org/InStock" }
  }
  </script>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --navy: #15295A;
      --navy-dark: #0D1B3E;
      --navy-mid: #1B2A4A;
      --green: #6CC24A;
      --green-dark: #52a335;
      --gray-dark: #3C424B;
      --gray-mid: #5a6270;
      --gray-light: #8a94a6;
      --bg-dark: #0D1B2A;
      --bg-card: #111d2e;
      --bg-card2: #162236;
      --text-primary: #f0f4ff;
      --text-secondary: #a8b4cc;
      --border: rgba(108,194,74,0.15);
      --border-subtle: rgba(255,255,255,0.07);
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg-dark); color: var(--text-primary); line-height: 1.6; }
    a { color: inherit; text-decoration: none; }

    /* NAV */
    nav {
      position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
      background: rgba(13,27,42,0.95); backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border-subtle);
      padding: 0 2rem; height: 68px;
      display: flex; align-items: center; justify-content: space-between;
    }
    .nav-logo { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 1.3rem; letter-spacing: -0.5px; }
    .nav-logo span { color: var(--green); }
    .nav-logo-icon { width: 32px; height: 32px; background: var(--green); border-radius: 6px; display: flex; align-items: center; justify-content: center; }
    .nav-logo-icon svg { width: 20px; height: 20px; fill: #fff; }
    .nav-links { display: flex; align-items: center; gap: 0.25rem; }
    .nav-links a, .nav-dropdown-trigger {
      color: var(--text-secondary); font-size: 0.875rem; font-weight: 500;
      padding: 0.5rem 0.9rem; border-radius: 6px; transition: all 0.2s;
      cursor: pointer; background: none; border: none; font-family: inherit;
    }
    .nav-links a:hover, .nav-dropdown-trigger:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
    .nav-dropdown { position: relative; }
    .nav-dropdown-trigger { display: flex; align-items: center; gap: 6px; }
    .nav-dropdown-trigger::after { content: '▾'; font-size: 0.7rem; transition: transform 0.2s; }
    .nav-dropdown:hover .nav-dropdown-trigger::after { transform: rotate(180deg); }
    .nav-dropdown-menu {
      display: none; position: absolute; top: calc(100% + 8px); left: 0;
      background: var(--bg-card2); border: 1px solid var(--border-subtle);
      border-radius: 10px; padding: 0.5rem; min-width: 200px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.5);
    }
    .nav-dropdown:hover .nav-dropdown-menu { display: block; }
    .nav-dropdown-menu a {
      display: block; padding: 0.6rem 1rem; border-radius: 6px;
      color: var(--text-secondary); font-size: 0.875rem;
      transition: all 0.15s;
    }
    .nav-dropdown-menu a:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
    .nav-cta {
      background: var(--green); color: #fff; padding: 0.55rem 1.25rem;
      border-radius: 8px; font-weight: 600; font-size: 0.875rem;
      transition: all 0.2s; white-space: nowrap;
    }
    .nav-cta:hover { background: var(--green-dark); color: #fff; transform: translateY(-1px); }
    .nav-mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 0.5rem; }
    .nav-mobile-toggle span { display: block; width: 22px; height: 2px; background: var(--text-secondary); margin: 5px 0; transition: all 0.3s; }
    @media (max-width: 900px) {
      .nav-links { display: none; flex-direction: column; position: absolute; top: 68px; left: 0; right: 0; background: var(--bg-card2); padding: 1rem; border-bottom: 1px solid var(--border-subtle); gap: 0.25rem; }
      .nav-links.open { display: flex; }
      .nav-mobile-toggle { display: block; }
      .nav-dropdown-menu { position: static; box-shadow: none; border: none; background: rgba(255,255,255,0.03); margin-top: 4px; }
      .nav-dropdown:hover .nav-dropdown-menu { display: none; }
      .nav-dropdown-menu.open { display: block; }
    }

    /* HERO */
    .hero {
      min-height: 100vh; padding-top: 68px;
      background: linear-gradient(135deg, #0D1B2A 0%, #0f2240 50%, #0a1a30 100%);
      display: flex; align-items: center; position: relative; overflow: hidden;
    }
    .hero-bg-grid {
      position: absolute; inset: 0; opacity: 0.04;
      background-image: linear-gradient(rgba(108,194,74,1) 1px, transparent 1px),
        linear-gradient(90deg, rgba(108,194,74,1) 1px, transparent 1px);
      background-size: 60px 60px;
    }
    .hero-bg-glow {
      position: absolute; top: 20%; right: 10%;
      width: 600px; height: 600px;
      background: radial-gradient(circle, rgba(108,194,74,0.08) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-content {
      max-width: 1200px; margin: 0 auto; padding: 4rem 2rem;
      display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center;
      position: relative; z-index: 1;
    }
    .hero-tag {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(108,194,74,0.1); border: 1px solid rgba(108,194,74,0.3);
      color: var(--green); padding: 0.4rem 0.9rem; border-radius: 100px;
      font-size: 0.75rem; font-weight: 600; letter-spacing: 1px; text-transform: uppercase;
      margin-bottom: 1.5rem;
    }
    .hero-tag::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: var(--green); animation: pulse 2s infinite; }
    @keyframes pulse { 0%,100% { opacity:1; } 50% { opacity:0.3; } }
    .hero h1 {
      font-size: clamp(2rem, 4vw, 3.25rem); font-weight: 800;
      line-height: 1.1; letter-spacing: -1px; margin-bottom: 1.5rem;
    }
    .hero h1 .accent { color: var(--green); }
    .hero-subtitle { font-size: 1.1rem; color: var(--text-secondary); line-height: 1.7; margin-bottom: 2.5rem; max-width: 520px; }
    .hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }
    .btn-primary {
      background: var(--green); color: #fff; padding: 0.85rem 1.75rem;
      border-radius: 8px; font-weight: 700; font-size: 0.95rem;
      transition: all 0.2s; display: inline-flex; align-items: center; gap: 8px;
    }
    .btn-primary:hover { background: var(--green-dark); transform: translateY(-2px); box-shadow: 0 8px 30px rgba(108,194,74,0.3); }
    .btn-secondary {
      background: transparent; color: var(--text-primary); padding: 0.85rem 1.75rem;
      border-radius: 8px; font-weight: 600; font-size: 0.95rem;
      border: 1px solid rgba(255,255,255,0.2); transition: all 0.2s;
    }
    .btn-secondary:hover { border-color: var(--green); color: var(--green); }
    .hero-visual { position: relative; }
    .hero-diagram {
      background: var(--bg-card2); border: 1px solid var(--border-subtle);
      border-radius: 16px; padding: 1.5rem; position: relative;
      box-shadow: 0 40px 80px rgba(0,0,0,0.4);
    }
    .hero-diagram-title { font-size: 0.7rem; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase; color: var(--green); margin-bottom: 1.5rem; }
    .ecosystem-diagram { display: flex; flex-direction: column; gap: 1rem; }
    .eco-node {
      display: flex; align-items: center; gap: 1rem;
      background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle);
      border-radius: 10px; padding: 1rem 1.25rem; transition: all 0.2s;
    }
    .eco-node:hover { border-color: rgba(108,194,74,0.3); background: rgba(108,194,74,0.04); }
    .eco-node-icon {
      width: 44px; height: 44px; border-radius: 10px;
      background: rgba(108,194,74,0.12); display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .eco-node-icon svg { width: 22px; height: 22px; }
    .eco-node-label { font-size: 0.8rem; font-weight: 600; color: var(--text-primary); margin-bottom: 2px; }
    .eco-node-desc { font-size: 0.72rem; color: var(--text-secondary); }
    .eco-connector {
      display: flex; align-items: center; justify-content: center;
      height: 20px; position: relative;
    }
    .eco-connector::before {
      content: ''; position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%);
      width: 1px; height: 20px; background: linear-gradient(to bottom, transparent, var(--green), transparent);
    }
    .hero-stats { display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; margin-top: 1rem; }
    .hero-stat { text-align: center; padding: 0.75rem; background: rgba(255,255,255,0.03); border-radius: 8px; }
    .hero-stat-num { font-size: 1.4rem; font-weight: 800; color: var(--green); }
    .hero-stat-label { font-size: 0.68rem; color: var(--text-secondary); margin-top: 2px; }
    @media (max-width: 900px) {
      .hero-content { grid-template-columns: 1fr; gap: 2.5rem; }
      .hero-visual { display: none; }
    }

    /* PRODUCT BANNER */
    .product-banner {
      background: linear-gradient(90deg, var(--navy) 0%, #0f2550 100%);
      border-top: 1px solid rgba(108,194,74,0.2); border-bottom: 1px solid rgba(108,194,74,0.2);
      padding: 1.25rem 2rem;
    }
    .product-banner-inner {
      max-width: 1200px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap;
    }
    .product-banner-label { font-size: 0.7rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--green); margin-bottom: 0.25rem; }
    .product-banner-title { font-size: 1.1rem; font-weight: 700; }
    .product-banner-tag {
      display: inline-block; background: rgba(108,194,74,0.15); color: var(--green);
      border: 1px solid rgba(108,194,74,0.3); padding: 0.25rem 0.75rem;
      border-radius: 100px; font-size: 0.75rem; font-weight: 600; margin-top: 0.4rem;
    }
    .btn-ghost {
      border: 1px solid var(--green); color: var(--green);
      padding: 0.6rem 1.25rem; border-radius: 8px; font-weight: 600; font-size: 0.875rem;
      transition: all 0.2s; white-space: nowrap;
    }
    .btn-ghost:hover { background: var(--green); color: #fff; }

    /* SECTIONS COMMON */
    section { padding: 5rem 2rem; }
    .section-inner { max-width: 1200px; margin: 0 auto; }
    .section-label { font-size: 0.72rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--green); margin-bottom: 0.75rem; }
    .section-title { font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 800; letter-spacing: -0.5px; margin-bottom: 1rem; }
    .section-desc { color: var(--text-secondary); font-size: 1rem; line-height: 1.75; max-width: 680px; margin-bottom: 3rem; }

    /* USE CASES */
    .use-cases { background: var(--bg-dark); }
    .use-cases-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; margin-bottom: 2.5rem; }
    @media (max-width: 900px) { .use-cases-grid { grid-template-columns: repeat(2,1fr); } }
    @media (max-width: 560px) { .use-cases-grid { grid-template-columns: 1fr; } }
    .use-case-card {
      background: var(--bg-card); border: 1px solid var(--border-subtle);
      border-radius: 12px; padding: 1.75rem;
      transition: all 0.25s; cursor: pointer;
    }
    .use-case-card:hover {
      border-color: rgba(108,194,74,0.35); transform: translateY(-4px);
      box-shadow: 0 16px 40px rgba(0,0,0,0.3);
    }
    .use-case-icon {
      width: 48px; height: 48px; border-radius: 10px;
      background: rgba(108,194,74,0.1); display: flex; align-items: center; justify-content: center;
      margin-bottom: 1.25rem;
    }
    .use-case-icon svg { width: 24px; height: 24px; }
    .use-case-title { font-size: 0.95rem; font-weight: 700; margin-bottom: 0.6rem; }
    .use-case-desc { font-size: 0.8rem; color: var(--text-secondary); line-height: 1.6; }
    .use-case-arrow { color: var(--green); font-size: 0.8rem; margin-top: 1rem; display: flex; align-items: center; gap: 4px; font-weight: 600; }
    .use-cases-cta { text-align: center; }

    /* PLATFORM OVERVIEW DIAGRAM */
    .platform-diagram { background: var(--bg-card); }
    .platform-pillars { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.5rem; }
    @media (max-width: 760px) { .platform-pillars { grid-template-columns: 1fr; } }
    .pillar {
      border: 1px solid var(--border-subtle); border-radius: 14px;
      overflow: hidden; position: relative;
    }
    .pillar-header {
      background: linear-gradient(135deg, rgba(21,41,90,0.8) 0%, rgba(15,33,72,0.9) 100%);
      padding: 1.5rem; border-bottom: 1px solid var(--border-subtle);
    }
    .pillar-num { font-size: 0.65rem; font-weight: 700; letter-spacing: 2px; color: var(--green); text-transform: uppercase; margin-bottom: 0.5rem; }
    .pillar-title { font-size: 1.05rem; font-weight: 700; }
    .pillar-body { padding: 1.5rem; background: var(--bg-card2); }
    .pillar-desc { font-size: 0.82rem; color: var(--text-secondary); line-height: 1.65; margin-bottom: 1.25rem; }
    .pillar-items { display: flex; flex-direction: column; gap: 0.5rem; }
    .pillar-item {
      display: flex; align-items: center; gap: 8px;
      font-size: 0.78rem; color: var(--text-secondary);
    }
    .pillar-item::before { content: ''; width: 4px; height: 4px; border-radius: 50%; background: var(--green); flex-shrink: 0; }

    /* INDUSTRY TABS */
    .industry-tabs-section { background: var(--bg-dark); }
    .tabs-nav {
      display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 2rem;
      border-bottom: 1px solid var(--border-subtle); padding-bottom: 0;
    }
    .tab-btn {
      background: none; border: none; border-bottom: 2px solid transparent;
      color: var(--text-secondary); font-size: 0.875rem; font-weight: 600;
      padding: 0.75rem 1.25rem; cursor: pointer; font-family: inherit;
      transition: all 0.2s; margin-bottom: -1px;
    }
    .tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
    .tab-btn:hover:not(.active) { color: var(--text-primary); }
    .tab-content { display: none; }
    .tab-content.active { display: block; animation: fadeIn 0.3s ease; }
    @keyframes fadeIn { from { opacity:0; transform: translateY(6px); } to { opacity:1; transform: translateY(0); } }
    .industry-content {
      display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: start;
    }
    @media (max-width: 760px) { .industry-content { grid-template-columns: 1fr; } }
    .industry-desc { color: var(--text-secondary); line-height: 1.75; margin-bottom: 1.5rem; }
    .industry-list { display: flex; flex-direction: column; gap: 0.75rem; }
    .industry-list-item {
      display: flex; align-items: flex-start; gap: 12px;
      padding: 0.85rem 1rem; background: var(--bg-card);
      border: 1px solid var(--border-subtle); border-radius: 8px;
    }
    .industry-list-item .check { color: var(--green); font-size: 0.9rem; margin-top: 1px; flex-shrink: 0; }
    .industry-list-item-text { font-size: 0.85rem; color: var(--text-secondary); }
    .industry-list-item-title { font-size: 0.875rem; font-weight: 600; color: var(--text-primary); margin-bottom: 2px; }
    .industry-visual {
      background: var(--bg-card2); border: 1px solid var(--border-subtle);
      border-radius: 14px; padding: 1.75rem;
    }
    .industry-product-grid { display: flex; flex-direction: column; gap: 0.75rem; margin-top: 1rem; }
    .industry-product-tag {
      display: flex; align-items: center; gap: 10px;
      background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle);
      border-radius: 8px; padding: 0.75rem 1rem; font-size: 0.8rem;
    }
    .industry-product-tag .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--green); flex-shrink: 0; }
    .industry-product-name { font-weight: 600; }
    .industry-product-func { color: var(--text-secondary); font-size: 0.75rem; margin-left: auto; }

    /* COMPANY CULTURE */
    .culture { background: linear-gradient(135deg, var(--navy) 0%, #0a1f45 100%); }
    .culture-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
    @media (max-width: 760px) { .culture-inner { grid-template-columns: 1fr; } }
    .culture-stats { display: grid; grid-template-columns: repeat(2,1fr); gap: 1rem; }
    .culture-stat {
      background: rgba(255,255,255,0.05); border: 1px solid var(--border-subtle);
      border-radius: 12px; padding: 1.5rem; text-align: center;
    }
    .culture-stat-num { font-size: 2rem; font-weight: 800; color: var(--green); }
    .culture-stat-label { font-size: 0.8rem; color: var(--text-secondary); margin-top: 4px; }

    /* RENEWABLES */
    .renewables {
      background: var(--bg-dark);
      border-top: 1px solid var(--border-subtle);
    }
    .renewables-inner {
      background: linear-gradient(135deg, #0d2d1a 0%, #0f1f0a 100%);
      border: 1px solid rgba(108,194,74,0.2); border-radius: 16px;
      padding: 3rem; display: grid; grid-template-columns: 1fr auto; gap: 3rem; align-items: center;
    }
    @media (max-width: 760px) { .renewables-inner { grid-template-columns: 1fr; text-align: center; } }
    .renewables-label { color: var(--green); font-size: 0.72rem; font-weight: 700; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 0.75rem; }
    .renewables-title { font-size: 1.75rem; font-weight: 800; margin-bottom: 1rem; }
    .renewables-desc { color: var(--text-secondary); line-height: 1.7; }

    /* FOOTER */
    footer {
      background: #080f1a; border-top: 1px solid var(--border-subtle);
      padding: 4rem 2rem 2rem;
    }
    .footer-inner { max-width: 1200px; margin: 0 auto; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 3rem; margin-bottom: 3rem; }
    @media (max-width: 900px) { .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; } }
    @media (max-width: 560px) { .footer-grid { grid-template-columns: 1fr; } }
    .footer-brand p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.7; margin-top: 0.75rem; max-width: 280px; }
    .footer-col-title { font-size: 0.75rem; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--green); margin-bottom: 1.25rem; }
    .footer-col a { display: block; font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 0.6rem; transition: color 0.15s; }
    .footer-col a:hover { color: var(--text-primary); }
    .footer-portals { margin-top: 1.5rem; padding-top: 1.5rem; border-top: 1px solid var(--border-subtle); }
    .footer-portals-title { font-size: 0.72rem; font-weight: 600; color: var(--text-secondary); margin-bottom: 0.75rem; letter-spacing: 1px; text-transform: uppercase; }
    .footer-portals-links { display: flex; gap: 0.75rem; flex-wrap: wrap; }
    .footer-portal-link {
      font-size: 0.75rem; color: var(--text-secondary);
      border: 1px solid var(--border-subtle); border-radius: 6px;
      padding: 0.35rem 0.75rem; transition: all 0.15s;
    }
    .footer-portal-link:hover { color: var(--green); border-color: rgba(108,194,74,0.3); }
    .footer-bottom {
      padding-top: 1.5rem; border-top: 1px solid var(--border-subtle);
      display: flex; justify-content: space-between; align-items: center;
      gap: 1rem; flex-wrap: wrap;
      font-size: 0.8rem; color: var(--text-secondary);
    }

    /* COOKIE BANNER */
    .cookie-banner {
      position: fixed; bottom: 1.5rem; left: 1.5rem; right: 1.5rem; z-index: 2000;
      background: var(--bg-card2); border: 1px solid var(--border-subtle);
      border-radius: 14px; padding: 1.25rem 1.5rem;
      display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; flex-wrap: wrap;
      box-shadow: 0 20px 60px rgba(0,0,0,0.5);
      max-width: 900px; margin: 0 auto;
    }
    .cookie-text { font-size: 0.85rem; color: var(--text-secondary); flex: 1; min-width: 200px; }
    .cookie-text strong { color: var(--text-primary); }
    .cookie-actions { display: flex; gap: 0.75rem; }
    .cookie-accept {
      background: var(--green); color: #fff; border: none;
      padding: 0.55rem 1.25rem; border-radius: 8px; font-weight: 600;
