<script>
  document.getElementById('mobileToggle').addEventListener('click', () => {
    document.getElementById('navLinks').classList.toggle('open');
  });

  // Accordion
  document.querySelectorAll('.accordion-trigger').forEach(trigger => {
    trigger.addEventListener('click', () => {
      const target = trigger.dataset.target;
      const isActive = trigger.classList.contains('active');
      document.querySelectorAll('.accordion-trigger').forEach(t => { t.classList.remove('active'); });
      document.querySelectorAll('.accordion-body').forEach(b => b.classList.remove('open'));
      document.querySelectorAll('.feature-detail').forEach(d => d.classList.remove('active'));
      if (!isActive) {
        trigger.classList.add('active');
        document.getElementById(target + '-body').classList.add('open');
        document.getElementById(target + '-detail').classList.add('active');
      }
    });
  });

  // Animate progress bars on scroll
  const observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.querySelectorAll('.progress-bar').forEach(bar => {
          const w = bar.style.width;
          bar.style.width = '0';
          setTimeout(() => { bar.style.width = w; }, 100);
        });
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });
  document.querySelectorAll('.timeline').forEach(el => observer.observe(el));
</script>
