  <link rel="canonical" href="https://www.wellstream.com/integration">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --navy: #15295A; --green: #6CC24A; --green-dark: #52a335;
      --bg-dark: #0D1B2A; --bg-card: #111d2e; --bg-card2: #162236;
      --text-primary: #f0f4ff; --text-secondary: #a8b4cc;
      --border-subtle: rgba(255,255,255,0.07); --border-green: rgba(108,194,74,0.15);
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg-dark); color: var(--text-primary); line-height: 1.6; }
    a { color: inherit; text-decoration: none; }

    nav { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; background: rgba(13,27,42,0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border-subtle); padding: 0 2rem; height: 68px; display: flex; align-items: center; justify-content: space-between; }
    .nav-logo { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 1.3rem; letter-spacing: -0.5px; }
    .nav-logo span { color: var(--green); }
    .nav-logo-icon { width: 32px; height: 32px; background: var(--green); border-radius: 6px; display: flex; align-items: center; justify-content: center; }
    .nav-logo-icon svg { width: 20px; height: 20px; fill: #fff; }
    .nav-links { display: flex; align-items: center; gap: 0.25rem; }
    .nav-links a, .nav-dropdown-trigger { color: var(--text-secondary); font-size: 0.875rem; font-weight: 500; padding: 0.5rem 0.9rem; border-radius: 6px; transition: all 0.2s; cursor: pointer; background: none; border: none; font-family: inherit; }
    .nav-links a:hover, .nav-dropdown-trigger:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
    .nav-dropdown { position: relative; }
    .nav-dropdown-trigger { display: flex; align-items: center; gap: 6px; }
    .nav-dropdown-trigger::after { content: '▾'; font-size: 0.7rem; }
    .nav-dropdown:hover .nav-dropdown-trigger::after { transform: rotate(180deg); }
    .nav-dropdown-menu { display: none; position: absolute; top: calc(100% + 8px); left: 0; background: var(--bg-card2); border: 1px solid var(--border-subtle); border-radius: 10px; padding: 0.5rem; min-width: 200px; box-shadow: 0 20px 60px rgba(0,0,0,0.5); }
    .nav-dropdown:hover .nav-dropdown-menu { display: block; }
    .nav-dropdown-menu a { display: block; padding: 0.6rem 1rem; border-radius: 6px; color: var(--text-secondary); font-size: 0.875rem; transition: all 0.15s; }
    .nav-dropdown-menu a:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
    .nav-cta { background: var(--green); color: #fff; padding: 0.55rem 1.25rem; border-radius: 8px; font-weight: 600; font-size: 0.875rem; transition: all 0.2s; }
    .nav-cta:hover { background: var(--green-dark); color: #fff; }
    .nav-mobile-toggle { display: none; background: none; border: none; cursor: pointer; padding: 0.5rem; }
    .nav-mobile-toggle span { display: block; width: 22px; height: 2px; background: var(--text-secondary); margin: 5px 0; }
    @media (max-width: 900px) { .nav-links { display: none; flex-direction: column; position: absolute; top: 68px; left: 0; right: 0; background: var(--bg-card2); padding: 1rem; border-bottom: 1px solid var(--border-subtle); gap: 0.25rem; } .nav-links.open { display: flex; } .nav-mobile-toggle { display: block; } }

    .page-hero { padding-top: 68px; min-height: 380px; background: linear-gradient(135deg, #0D1B2A 0%, #0a2030 50%, #091520 100%); display: flex; align-items: center; position: relative; overflow: hidden; }
    .page-hero-grid { position: absolute; inset: 0; opacity: 0.03; background-image: linear-gradient(rgba(108,194,74,1) 1px, transparent 1px), linear-gradient(90deg, rgba(108,194,74,1) 1px, transparent 1px); background-size: 60px 60px; }
    .page-hero-inner { max-width: 1200px; margin: 0 auto; padding: 4rem 2rem; position: relative; z-index: 1; }
    .breadcrumb { font-size: 0.75rem; color: var(--text-secondary); margin-bottom: 1rem; }
    .breadcrumb a { color: var(--green); }
    .page-hero-label { font-size: 0.72rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--green); margin-bottom: 0.75rem; }
    .page-hero h1 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; letter-spacing: -1px; max-width: 700px; }
    .page-hero p { color: var(--text-secondary); font-size: 1.05rem; margin-top: 1rem; max-width: 620px; line-height: 1.7; }
    .integration-logos { display: flex; gap: 1rem; margin-top: 2rem; flex-wrap: wrap; }
    .integration-logo-tag { background: rgba(255,255,255,0.05); border: 1px solid var(--border-subtle); border-radius: 8px; padding: 0.4rem 0.9rem; font-size: 0.8rem; font-weight: 500; color: var(--text-secondary); }

    section { padding: 5rem 2rem; }
    .section-inner { max-width: 1200px; margin: 0 auto; }
    .section-label { font-size: 0.72rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--green); margin-bottom: 0.75rem; }
    .section-title { font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 800; letter-spacing: -0.5px; margin-bottom: 1rem; }
    .section-desc { color: var(--text-secondary); font-size: 1rem; line-height: 1.75; max-width: 680px; margin-bottom: 3rem; }
    .btn-primary { background: var(--green); color: #fff; padding: 0.85rem 1.75rem; border-radius: 8px; font-weight: 700; font-size: 0.95rem; transition: all 0.2s; display: inline-flex; align-items: center; gap: 8px; }
    .btn-primary:hover { background: var(--green-dark); transform: translateY(-2px); box-shadow: 0 8px 30px rgba(108,194,74,0.3); }

    /* OVERVIEW */
    .integration-overview { background: var(--bg-card); }
    .overview-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1.5rem; }
    @media (max-width: 760px) { .overview-grid { grid-template-columns: 1fr; } }
    .overview-card { background: var(--bg-dark); border: 1px solid var(--border-subtle); border-radius: 14px; padding: 2rem; text-align: center; transition: all 0.25s; cursor: pointer; }
    .overview-card:hover, .overview-card.active { border-color: rgba(108,194,74,0.4); background: rgba(108,194,74,0.03); }
    .overview-card-icon { width: 64px; height: 64px; border-radius: 14px; background: rgba(108,194,74,0.1); display: flex; align-items: center; justify-content: center; margin: 0 auto 1.25rem; }
    .overview-card-icon svg { width: 32px; height: 32px; }
    .overview-card-title { font-size: 1.05rem; font-weight: 700; margin-bottom: 0.5rem; }
    .overview-card-desc { font-size: 0.83rem; color: var(--text-secondary); line-height: 1.65; }

    /* INTEGRATION TABS */
    .integration-tabs-section { background: var(--bg-dark); }
    .tabs-nav { display: flex; gap: 0.5rem; flex-wrap: wrap; margin-bottom: 2.5rem; border-bottom: 1px solid var(--border-subtle); padding-bottom: 0; }
    .tab-btn { background: none; border: none; border-bottom: 2px solid transparent; color: var(--text-secondary); font-size: 0.9rem; font-weight: 600; padding: 0.85rem 1.5rem; cursor: pointer; font-family: inherit; transition: all 0.2s; margin-bottom: -1px; }
    .tab-btn.active { color: var(--green); border-bottom-color: var(--green); }
    .tab-btn:hover:not(.active) { color: var(--text-primary); }
    .tab-content { display: none; }
    .tab-content.active { display: block; animation: fadeIn 0.3s ease; }
    @keyframes fadeIn { from { opacity:0; transform: translateY(6px); } to { opacity:1; transform: translateY(0); } }

    .integration-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: start; }
    @media (max-width: 860px) { .integration-detail { grid-template-columns: 1fr; } }
    .integration-detail-desc { color: var(--text-secondary); line-height: 1.75; margin-bottom: 1.5rem; }
    .integration-benefits { display: flex; flex-direction: column; gap: 0.75rem; }
    .integration-benefit { display: flex; align-items: flex-start; gap: 12px; padding: 0.85rem 1rem; background: var(--bg-card); border: 1px solid var(--border-subtle); border-radius: 8px; transition: border-color 0.2s; }
    .integration-benefit:hover { border-color: rgba(108,194,74,0.25); }
    .integration-benefit-check { color: var(--green); font-size: 0.9rem; flex-shrink: 0; margin-top: 1px; }
    .integration-benefit-title { font-size: 0.875rem; font-weight: 600; margin-bottom: 2px; }
    .integration-benefit-desc { font-size: 0.8rem; color: var(--text-secondary); }
    .integration-code-block { background: #050e18; border: 1px solid rgba(108,194,74,0.15); border-radius: 12px; padding: 1.5rem; font-family: 'Courier New', monospace; font-size: 0.8rem; overflow-x: auto; }
    .code-comment { color: #4a7a3a; }
    .code-key { color: #6CC24A; }
    .code-string { color: #98d977; }
    .code-value { color: #7eb8d0; }
    .code-keyword { color: #c792ea; }
    .integration-visual { background: var(--bg-card2); border: 1px solid var(--border-subtle); border-radius: 14px; padding: 1.75rem; }
    .integration-visual-title { font-size: 0.72rem; font-weight: 600; letter-spacing: 2px; text-transform: uppercase; color: var(--green); margin-bottom: 1.5rem; }
    .flow-diagram { display: flex; flex-direction: column; gap: 0.75rem; }
    .flow-step { display: flex; align-items: center; gap: 12px; background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle); border-radius: 8px; padding: 0.85rem 1rem; }
    .flow-step-num { width: 28px; height: 28px; border-radius: 50%; background: rgba(108,194,74,0.12); border: 1px solid rgba(108,194,74,0.3); color: var(--green); font-size: 0.75rem; font-weight: 700; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .flow-step-label { font-size: 0.83rem; font-weight: 500; }
    .flow-connector { height: 12px; width: 1px; background: rgba(108,194,74,0.3); margin-left: 14px; }
    .dashboard-preview { background: var(--bg-dark); border: 1px solid var(--border-subtle); border-radius: 10px; padding: 1.25rem; }
    .dashboard-bar-row { display: flex; align-items: center; gap: 10px; margin-bottom: 0.75rem; }
    .dashboard-bar-label { font-size: 0.72rem; color: var(--text-secondary); min-width: 80px; }
    .dashboard-bar-wrap { flex: 1; background: rgba(255,255,255,0.05); border-radius: 4px; height: 8px; overflow: hidden; }
    .dashboard-bar { height: 100%; border-radius: 4px; background: linear-gradient(90deg, var(--green), #52a335); }
    .dashboard-bar-val { font-size: 0.72rem; font-weight: 600; color: var(--green); min-width: 36px; text-align: right; }

    /* ETL BENEFITS */
    .etl-benefits { background: var(--bg-card); }
    .etl-grid { display: grid; grid-template-columns: repeat(2,1fr); gap: 1.5rem; }
    @media (max-width: 760px) { .etl-grid { grid-template-columns: 1fr; } }
    .etl-card { background: var(--bg-dark); border: 1px solid var(--border-subtle); border-radius: 14px; padding: 1.75rem; transition: all 0.25s; display: flex; gap: 1.25rem; align-items: flex-start; }
    .etl-card:hover { border-color: rgba(108,194,74,0.3); transform: translateY(-3px); }
    .etl-card-icon { width: 48px; height: 48px; border-radius: 10px; background: rgba(108,194,74,0.1); display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .etl-card-icon svg { width: 24px; height: 24px; }
    .etl-card-title { font-size: 0.95rem; font-weight: 700; margin-bottom: 0.5rem; }
    .etl-card-desc { font-size: 0.83rem; color: var(--text-secondary); line-height: 1.65; }

    /* CTA */
    .integration-cta { background: var(--bg-dark); }
    .integration-cta-box { background: linear-gradient(135deg, var(--navy) 0%, #0a1f45 100%); border: 1px solid rgba(108,194,74,0.2); border-radius: 16px; padding: 4rem; text-align: center; }
    .integration-cta-box h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 800; margin-bottom: 1rem; }
    .integration-cta-box p { color: var(--text-secondary); font-size: 1rem; line-height: 1.7; max-width: 520px; margin: 0 auto 2rem; }

    footer { background: #080f1a; border-top: 1px solid var(--border-subtle); padding: 4rem 2rem 2rem; }
    .footer-inner { max-width: 1200px; margin: 0 auto; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 3rem; margin-bottom: 3rem; }
    @media (max-width: 900px) { .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; } }
    @media (max-width: 560px) { .footer-grid { grid-template-columns: 1fr; } }
    .footer-brand p { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.7; margin-top: 0.75rem; max-width: 280px; }
    .footer-col-title { font-size: 0.75rem; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--green); margin-bottom: 1.25rem; }
    .footer-col a { display: block; font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 0.6rem; transition: color 0.15s; }
    .footer-col a:hover { color: var(--text-primary); }
    .footer-portals { margin-top: 1.5rem; padding-top: 1.5rem; border-top: 1px solid var(--border-subtle); }
    .footer-portals-title { font-size: 0.72rem; font-weight: 600; color: var(--text-secondary); margin-bottom: 0.75rem; letter-spacing: 1px; text-transform: uppercase; }
    .footer-portals-links { display: flex; gap: 0.75rem; flex-wrap: wrap; }
    .footer-portal-link { font-size: 0.75rem; color: var(--text-secondary); border: 1px solid var(--border-subtle); border-radius: 6px; padding: 0.35rem 0.75rem; transition: all 0.15s; }
    .footer-portal-link:hover { color: var(--green); border-color: rgba(108,194,74,0.3); }
    .footer-bottom { padding-top: 1.5rem; border-top: 1px solid var(--border-subtle); display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; font-size: 0.8rem; color: var(--text-secondary); }
  </style>
</head>
