<section class="integration-tabs-section">
  <div class="section-inner">
    <div class="section-label">Integration Details</div>
    <h2 class="section-title">Choose Your Integration Approach</h2>
    <div class="tabs-nav" role="tablist">
      <button class="tab-btn active" data-tab="etl" role="tab" aria-selected="true">ETL</button>
      <button class="tab-btn" data-tab="apis" role="tab" aria-selected="false">APIs</button>
