    <!-- ETL TAB -->
    <div class="tab-content active" id="tab-etl">
      <div class="integration-detail">
        <div>
          <h3 style="font-size:1.2rem;font-weight:700;margin-bottom:1rem;">Automated ETL Pipelines</h3>
          <p class="integration-detail-desc">WellStream's managed ETL service handles the complexity of multi-source data ingestion, transformation, and loading — so your team focuses on analysis, not plumbing. Schedule pipelines, define transformation rules, and monitor job status from a single interface.</p>
          <div class="integration-benefits">
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Read-Only Snowflake Access</div><div class="integration-benefit-desc">Query WellStream data directly in Snowflake without impacting production performance.</div></div></div>
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Supports BI Warehousing</div><div class="integration-benefit-desc">Feed Power BI, Tableau, or Spotfire with clean, structured energy data pipelines.</div></div></div>
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Handles Complex Use Cases</div><div class="integration-benefit-desc">Map multi-source data from SCADA, accounting, and regulatory systems into unified schemas.</div></div></div>
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Improves System Interoperability</div><div class="integration-benefit-desc">Bridge legacy databases and modern cloud applications with managed ETL orchestration.</div></div></div>
          </div>
        </div>
        <div class="integration-visual">
          <div class="integration-visual-title">ETL Pipeline Flow</div>
          <div class="flow-diagram">
            <div class="flow-step"><div class="flow-step-num">1</div><div class="flow-step-label">Extract — Pull data from source systems</div></div>
            <div class="flow-connector"></div>
            <div class="flow-step"><div class="flow-step-num">2</div><div class="flow-step-label">Transform — Apply business rules & mapping</div></div>
            <div class="flow-connector"></div>
            <div class="flow-step"><div class="flow-step-num">3</div><div class="flow-step-label">Validate — Quality checks & anomaly detection</div></div>
            <div class="flow-connector"></div>
            <div class="flow-step"><div class="flow-step-num">4</div><div class="flow-step-label">Load — Deliver to destination systems</div></div>
            <div class="flow-connector"></div>
            <div class="flow-step"><div class="flow-step-num">5</div><div class="flow-step-label">Monitor — Track job status & alerting</div></div>
          </div>
        </div>
      </div>
