    <!-- APIs TAB -->
    <div class="tab-content" id="tab-apis">
      <div class="integration-detail">
        <div>
          <h3 style="font-size:1.2rem;font-weight:700;margin-bottom:1rem;">RESTful APIs</h3>
          <p class="integration-detail-desc">WellStream's comprehensive REST API gives developers programmatic access to all platform data and operations. Use our API to build custom applications, automate workflows, or integrate WellStream data into your existing enterprise systems in real time.</p>
          <div class="integration-benefits">
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Comprehensive Coverage</div><div class="integration-benefit-desc">API endpoints for wells, production, land, reporting, and administration modules.</div></div></div>
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">OAuth 2.0 Security</div><div class="integration-benefit-desc">Token-based authentication with role-based access control and full audit logging.</div></div></div>
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Real-Time Data Access</div><div class="integration-benefit-desc">Pull live operational data for custom dashboards, mobile apps, and third-party tools.</div></div></div>
            <div class="integration-benefit"><span class="integration-benefit-check">✓</span><div><div class="integration-benefit-title">Developer Documentation</div><div class="integration-benefit-desc">Full OpenAPI specification with interactive sandbox for testing and integration development.</div></div></div>
          </div>
        </div>
