<script>
  document.getElementById('mobileToggle').addEventListener('click', () => document.getElementById('navLinks').classList.toggle('open'));

  const requiredFields = ['firstName', 'lastName', 'email', 'company', 'jobTitle', 'country'];

  function validateEmail(val) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val);
  }

  function validateField(id) {
    const el = document.getElementById(id);
    const errEl = document.getElementById('err-' + id);
    let valid = true;
    if (!el) return true;
    const val = el.value.trim();
    if (!val) {
      valid = false;
    } else if (id === 'email' && !validateEmail(val)) {
      valid = false;
      if (errEl) errEl.textContent = 'Please enter a valid email address.';
    }
    el.classList.toggle('error', !valid);
    if (errEl) errEl.classList.toggle('show', !valid);
    return valid;
  }

  requiredFields.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('blur', () => validateField(id));
  });

  document.getElementById('demoForm').addEventListener('submit', function(e) {
    e.preventDefault();
    let allValid = true;
    requiredFields.forEach(id => { if (!validateField(id)) allValid = false; });
    if (!allValid) return;
    const btn = document.getElementById('submitBtn');
    btn.disabled = true;
    btn.textContent = 'Submitting…';
    setTimeout(() => {
      document.getElementById('formContainer').style.display = 'none';
      document.getElementById('formSuccess').classList.add('show');
    }, 800);
  });
</script>
